// Convierte un valor normalizado 0..1 al dominio fisico segun la curva del parametro.
// Si el parametro no tiene curva definida, retorna el valor tal cual.
inline float normalizedToDomain (const ParameterMeta& entry, float t) noexcept
{
    // Clamp t to [0,1] para evitar desbordamiento o NaN
    float tClamped = std::clamp(t, 0.0f, 1.0f);

    // NOTA: wire (transporte: -1=None, 0=CC, 1=SysEx, 2=Nrpn) es ORTOGONOAL al
    // mapeo de dominio y NO debe cortar aqui. Antes existia un branch
    // `if (wire == -1)` que devolvia clamp(t, domainMin, domainMax) — unidades
    // mezcladas (t normalizado 0..1 clamped a un rango fisico como [-12,+12]
    // dB), lo que rompia normalizedToDomain de todo param sin transporte
    // (p.ej. eqLowGain/eqHighGain: el master EQ recibia 0..1 en vez de
    // -12..+12 dB). Todos los params caen ahora al mismo curve switch de
    // abajo, que ya resuelve el caso sin rango fisico (devuelve t).

    // Extremos matematicos exactos (evita errores de redondeo float en e^(p1) o pow)
    if (entry.domainMin < entry.domainMax) {
        if (tClamped <= 0.0f) return entry.domainMin;
        if (tClamped >= 1.0f) return entry.domainMax;
    }

    float result = tClamped;

    // Aplicar curva segun entry.curve
    switch (entry.curve)
    {
        case 0: // Linear
        {
            if (entry.domainMin < entry.domainMax) {
                result = entry.domainMin + tClamped * (entry.domainMax - entry.domainMin);
            } else {
                result = tClamped;
            }
            break;
        }

        case 1: // Exp: curveP0 * e^(curveP1 * t)
        {
            float p0 = entry.curveP0;
            float p1 = entry.curveP1;
            // Si p0 es 0, usamos escala por defecto
            if (p0 <= 0.0f) p0 = 1.0f;
            result = p0 * std::exp(p1 * tClamped);
            break;
        }

        case 2: // Pow: t ^ curveP1 (con escalado a [domainMin, domainMax] si aplica)
        {
            float p1 = entry.curveP1;
            if (p1 <= 0.0f) p1 = 1.0f;
            float powered = std::pow(tClamped, p1);
            if (entry.domainMin < entry.domainMax) {
                result = entry.domainMin + powered * (entry.domainMax - entry.domainMin);
            } else {
                result = powered;
            }
            break;
        }

        case 3: // Lut: lookup table (no implementado en esta version basica)
        default:
            result = tClamped;
            break;
    }

    // DSP.7: Clamping estricto domainMin/domainMax para blindar el dominio fisico
    if (entry.domainMin < entry.domainMax) {
        result = std::clamp(result, entry.domainMin, entry.domainMax);
    }

    return result;
}

// Convierte del dominio fisico al rango normalizado 0..1
// Inverso de normalizedToDomain
inline float domainToNormalized (const ParameterMeta& entry, float domain) noexcept
{
    if (entry.wire == -1) {
        if (entry.domainMin < entry.domainMax) {
            float clamped = std::clamp(domain, entry.domainMin, entry.domainMax);
            return std::clamp((clamped - entry.domainMin) / (entry.domainMax - entry.domainMin), 0.0f, 1.0f);
        }
        return std::clamp(domain, 0.0f, 1.0f);
    }

    // Extremos matematicos exactos (evita imprecision float en inversas)
    if (entry.domainMin < entry.domainMax) {
        if (domain <= entry.domainMin) return 0.0f;
        if (domain >= entry.domainMax) return 1.0f;
    }

    float norm = domain;
    switch (entry.curve)
    {
        case 0: // Linear
        {
            if (entry.domainMin < entry.domainMax) {
                float clamped = std::clamp(domain, entry.domainMin, entry.domainMax);
                norm = (clamped - entry.domainMin) / (entry.domainMax - entry.domainMin);
            }
            break;
        }

        case 1: // Exp inverse: (1/curveP1) * ln(domain / curveP0)
        {
            float p0 = entry.curveP0;
            float p1 = entry.curveP1;
            if (p0 <= 0.0f) p0 = 1.0f;
            if (p1 <= 0.0f) p1 = 1.0f;
            if (domain <= 0.0f) {
                norm = 0.0f;
                break;
            }
            // Clamp domain/p0 to avoid log of negative or zero
            float ratio = domain / p0;
            if (ratio <= 0.0f) {
                norm = 0.0f;
                break;
            }
            norm = (1.0f / p1) * std::log(ratio);
            break;
        }

        case 2: // Pow inverse: ((d - domainMin) / span) ^ (1/curveP1)
        {
            float p1 = entry.curveP1;
            if (p1 <= 0.0f) p1 = 1.0f;
            float val = domain;
            if (entry.domainMin < entry.domainMax) {
                float clamped = std::clamp(domain, entry.domainMin, entry.domainMax);
                val = (clamped - entry.domainMin) / (entry.domainMax - entry.domainMin);
            }
            if (val < 0.0f) val = 0.0f;
            norm = std::pow(val, 1.0f / p1);
            break;
        }

        case 3: // Lut: no implementado
        default:
            norm = domain;
            break;
    }

    // DSP.7: Clamping estricto al rango normalizado [0.0f, 1.0f]
    return std::clamp(norm, 0.0f, 1.0f);
}

// Convierte un valor raw de wire (CC 0-127, NRPN etc.) al dominio fisico
inline float wireToDomain (const ParameterMeta& entry, uint16_t raw) noexcept
{
    // Normalizar raw a [0,1] segun wireCodec
    float t = 0.0f;
    switch (entry.wireCodec)
    {
        case 0: // Value: raw 0-127 -> t = raw/127.0
        case 1: // Bipolar: raw -128 to 127 -> t = (raw+128)/255.0 (adaptado)
        case 2: // Enum: no aplicable, retornar 0
        default:
            // Asumimos wire 0-127 para CC/Value
            t = raw / 127.0f;
            break;
    }
    return normalizedToDomain(entry, t);
}

// Convierte un valor del dominio fisico a raw de wire
inline uint16_t domainToWire (const ParameterMeta& entry, float domain) noexcept
{
    // Convertir dominio a normalizado primero
    float t = domainToNormalized(entry, domain);

    // Convertir normalizado a raw segun wireCodec
    uint16_t raw = 0;
    switch (entry.wireCodec)
    {
        case 0: // Value: raw = t * 127.0, clamp 0-127
        {
            float r = t * 127.0f;
            if (r < 0) r = 0;
            if (r > 127) r = 127;
            raw = static_cast<uint16_t>(r);
            break;
        }
        case 1: // Bipolar: raw = (t * 255.0) - 128, clamp -128 to 127
        {
            float r = (t * 255.0f) - 128.0f;
            if (r < -128) r = -128;
            if (r > 127) r = 127;
            raw = static_cast<uint16_t>(r);
            break;
        }
        case 2: // Enum: no aplicable
        default:
            raw = static_cast<uint16_t>(t * 127.0f);
            break;
    }
    return raw;
}

