{
    if (const auto* meta = getMetaById(id))
        return domainToNormalized (*meta, domain);
    return domain;
}

// Convertir raw wire -> dominio fisico
inline float wireToDomain (const char* id, uint16_t raw) noexcept
{
    if (const auto* meta = getMetaById(id))
        return wireToDomain (*meta, raw);
    return raw / 127.0f; // fallback
}

// Convertir dominio fisico -> raw wire
inline uint16_t domainToWire (const char* id, float domain) noexcept
{
    if (const auto* meta = getMetaById(id))
        return domainToWire (*meta, domain);
    return static_cast<uint16_t>(domain * 127.0f); // fallback
}

